/** Pending invites for a billable role. Viewer invites do not hold a seat. */
export async function countPendingBillableInvitations(
  orgId: OrgId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(invitations)
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        isNull(invitations.acceptedAt),
        isNull(invitations.revokedAt),
        inArray(invitations.role, [...BILLABLE_ROLES]),
      ),
    )
    .get();
  return row?.value ?? 0;
}

