/**
 * Seats in use for quota checks: billable active members plus pending
 * invitations for a billable role. Viewer members and viewer invites are free.
 */
export async function countSeatsInUse(orgId: OrgId): Promise<number> {
  const [members, pending] = await Promise.all([
    memberRepo.countBillableActiveMembers(orgId),
    invitationRepo.countPendingBillableInvitations(orgId),
  ]);
  return members + pending;
}

/** +1 when a role starts occupying a seat, -1 when it stops, 0 otherwise. */
function seatDelta(fromBillable: boolean, toBillable: boolean): number {
  return (toBillable ? 1 : 0) - (fromBillable ? 1 : 0);
}

